import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:3000/api';

const api = axios.create({
  baseURL: API_URL,
  headers: {
    'Content-Type': 'application/json',
  },
  timeout: 10000,
  // Bỏ withCredentials nếu backend không hỗ trợ CORS với credentials
  // withCredentials: true,
});

// Request Interceptor
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    console.error('[API] Request Error:', error);
    return Promise.reject(error);
  }
);

// Response Interceptor
api.interceptors.response.use(
  (response) => response.data,
  (error) => {
    console.error('[API] Response Error:', error);
    
    if (!error.response) {
      return Promise.reject({
        success: false,
        message: 'Network Error. Please check your connection.',
        code: 'NETWORK_ERROR'
      });
    }

    const { status, data } = error.response;
    let errorMessage = data?.message || 'An error occurred';

    switch (status) {
      case 400:
        if (data?.errors) {
          errorMessage = Object.values(data.errors).flat().join(', ');
        }
        break;
      case 401:
        errorMessage = 'Session expired. Please login again';
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        break;
      case 403:
        errorMessage = 'You do not have permission';
        break;
      case 404:
        errorMessage = 'Resource not found';
        break;
      case 500:
        errorMessage = 'Internal server error';
        break;
    }

    return Promise.reject({
      success: false,
      message: errorMessage,
      code: `HTTP_${status}`,
      status,
      data
    });
  }
);

// API Services
export const authAPI = {
  register: (userData) => api.post('/auth/signup', {
    username: userData.username?.trim(),
    email: userData.email?.toLowerCase().trim(),
    password: userData.password
  }),
  
  login: (credentials) => api.post('/auth/login', {
    usernameOrEmail: credentials.usernameOrEmail?.toLowerCase().trim(),
    password: credentials.password
  }),
  
  logout: () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    return Promise.resolve();
  },
  
  // Đổi thành endpoint đúng của bạn
  getProfile: () => api.get('/auth/signup') // hoặc '/auth/profile' tùy backend
};

export const productAPI = {
  getProducts: (params) => api.get('/products', { params }),
  getProductDetails: (id) => api.get(`/products/${id}`),
  createProduct: (productData) => api.post('/products', productData),
  updateProduct: (id, productData) => api.put(`/products/${id}`, productData),
  deleteProduct: (id) => api.delete(`/products/${id}`)
};

export default api;
